head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > yearSuffix]<br/>Calendar 컴포넌트의 연도 표시에 붙는 Suffix 텍스트를 설정합니다.",
    "validation" : [
        "String 으로 연도 숫자 뒤에 붙을 Suffix 텍스트를 설정합니다.",
        "Suffix 없이 연도만 표시하려면 '$blank' 를 설정합니다.",
        "값을 설정하지 않으면 언어 설정에 따라 '년', '年' 이 적용되며 영어의 경우 Suffix 가 설정되지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        yearSuffix : con_yearSuffix.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createLabel('label="yearSuffix 설정 후 연도 SelectBox 를 한번 팝업(클릭)해야 적용된 값 확인 가능"', '', 'label1');
    await $c.gcm.createBasicCalendar(cList, eList);
}



// [연도 SelectBox 아이템 확인] 버튼
// validation:
//  - yearSuffix 가 연도 SelectBox 아이템의 연도 숫자 뒤에 결합되어 표시됨
//  - '$blank' 설정 시 Suffix 없이 연도만 표시 (예: '2025')
//  - 미설정 시 언어 설정에 따라 '년' / '年' 적용 (영어는 Suffix 없음)
scwin.btn_getYearItems_onclick = function (e) {
    let labels = [];
    let itemTable = document.querySelector('[id$="target1_selectbox_year_itemTable"]');
    if (itemTable) {
        let rows = itemTable.querySelectorAll('.w2table_sb_row');
        rows.forEach(function (row) {
            let t = row.textContent.trim();
            if (t) labels.push(t);
        });
        // fallback: w2table_sb_row 미매칭 시 [id*="_item_"] 사용
        if (labels.length === 0) {
            let items = itemTable.querySelectorAll('[id*="_item_"]');
            items.forEach(function (it) {
                let t = it.textContent.trim();
                if (t) labels.push(t);
            });
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("[연도 SelectBox 아이템 목록] '" + labels.join(',') + "'");
};
